mkdir -p /tmp/transfer-race && cat > /tmp/transfer-race/race.ts <<'EOF'
import { resetDatabase } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-fcYJlx/app/src/migrate.ts";
import { createApp } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-fcYJlx/app/src/app.ts";
import { pool } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-fcYJlx/app/src/db.ts";
await resetDatabase();
const server = createApp().listen(0);
const base = `http://localhost:${(server.address() as any).port}`;
const post = (token: string, body: unknown) => fetch(`${base}/transfers`, { method: "POST", headers: { authorization: `Bearer ${token}`, "content-type": "application/json" }, body: JSON.stringify(body) });
// Alice (10000) and Bob (500) send to each other concurrently, plus a burst that overdraws Alice.
const jobs = [
  ...Array.from({ length: 20 }, () => post("alice-token", { toUserId: 2, amountCents: 1000 })),
  ...Array.from({ length: 10 }, () => post("bob-token", { toUserId: 1, amountCents: 100 })),
];
const statuses = (await Promise.all(jobs)).map((r) => r.status);
const count = (s: number) => statuses.filter((x) => x === s).length;
const { rows } = await pool.query("select user_id, balance_cents from wallets order by user_id");
const sum = rows.reduce((a, r) => a + r.balance_cents, 0);
console.log({ created: count(201), insufficient: count(409), other: statuses.filter((s) => s !== 201 && s !== 409), rows, sumBefore: 10500, sumAfter: sum });
server.close(); await pool.end();
EOF
node --import tsx /tmp/transfer-race/race.ts 2>&1 | tail -20; rm -rf /tmp/transfer-race
